
// Lista de produtos e armazenamento
let produtos = JSON.parse(localStorage.getItem("produtos")) || [
    {
            codigo: 1,
                    descricao: "Teclado",
                            quantidade: 10,
                                    valor: 50.00
                                        },
                                            {
                                                    codigo: 2,
                                                            descricao: "Mouse",
                                                                    quantidade: 15,
                                                                            valor: 30.00
                                                                                },
                                                                                    {
                                                                                            codigo: 3,
                                                                                                    descricao: "Monitor",
                                                                                                            quantidade: 5,
                                                                                                                    valor: 750.00
                                                                                                                        },
                                                                                                                            {
                                                                                                                                    codigo: 4,
                                                                                                                                            descricao: "Notebook",
                                                                                                                                                    quantidade: 3,
                                                                                                                                                            valor: 2500.00
                                                                                                                                                                }
                                                                                                                                                                ];

                                                                                                                                                                let proximoCodigo = Math.max(0, ...produtos.map(p => p.codigo)) + 1;

                                                                                                                                                                // Salvar produtos no navegador
                                                                                                                                                                function salvarProdutos() {
                                                                                                                                                                    localStorage.setItem("produtos", JSON.stringify(produtos));
                                                                                                                                                                    }

                                                                                                                                                                    // Validar produto
                                                                                                                                                                    function validarProduto(descricao, quantidade, valor) {
                                                                                                                                                                        if (!descricao.trim()) {
                                                                                                                                                                                alert("Informe a descrição do produto!");
                                                                                                                                                                                        return false;
                                                                                                                                                                                            }

                                                                                                                                                                                                if (!Number.isInteger(quantidade) || quantidade <= 0) {
                                                                                                                                                                                                        alert("Informe uma quantidade válida!");
                                                                                                                                                                                                                return false;
                                                                                                                                                                                                                    }

                                                                                                                                                                                                                        if (!Number.isFinite(valor) || valor <= 0) {
                                                                                                                                                                                                                                alert("Informe um valor válido!");
                                                                                                                                                                                                                                        return false;
                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                return true;
                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                // Cadastrar produto
                                                                                                                                                                                                                                                document.getElementById("formProduto")
                                                                                                                                                                                                                                                    .addEventListener("submit", function(event) {

                                                                                                                                                                                                                                                        event.preventDefault();

                                                                                                                                                                                                                                                            const descricao = document.getElementById("descricao").value;
                                                                                                                                                                                                                                                                const quantidade = Number(document.getElementById("quantidade").value);
                                                                                                                                                                                                                                                                    const valor = Number(document.getElementById("valor").value);

                                                                                                                                                                                                                                                                        if (!validarProduto(descricao, quantidade, valor)) {
                                                                                                                                                                                                                                                                                return;
                                                                                                                                                                                                                                                                                    }

                                                                                                                                                                                                                                                                                        const produto = {
                                                                                                                                                                                                                                                                                                codigo: proximoCodigo++,
                                                                                                                                                                                                                                                                                                        descricao: descricao.trim(),
                                                                                                                                                                                                                                                                                                                quantidade: quantidade,
                                                                                                                                                                                                                                                                                                                        valor: valor
                                                                                                                                                                                                                                                                                                                            };

                                                                                                                                                                                                                                                                                                                                produtos.push(produto);

                                                                                                                                                                                                                                                                                                                                    salvarProdutos();
                                                                                                                                                                                                                                                                                                                                        listarProdutos();

                                                                                                                                                                                                                                                                                                                                            this.reset();

                                                                                                                                                                                                                                                                                                                                                alert("Produto cadastrado com sucesso!");
                                                                                                                                                                                                                                                                                                                                                });

                                                                                                                                                                                                                                                                                                                                                // Listar produtos
                                                                                                                                                                                                                                                                                                                                                function listarProdutos(filtro = "") {
                                                                                                                                                                                                                                                                                                                                                    const tabela = document.getElementById("listaProdutos");

                                                                                                                                                                                                                                                                                                                                                        tabela.innerHTML = "";

                                                                                                                                                                                                                                                                                                                                                            const produtosFiltrados = produtos.filter(produto =>
                                                                                                                                                                                                                                                                                                                                                                    produto.descricao.toLowerCase().includes(filtro.toLowerCase())
                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                            produtosFiltrados.forEach(produto => {
                                                                                                                                                                                                                                                                                                                                                                                    const linha = document.createElement("tr");

                                                                                                                                                                                                                                                                                                                                                                                            const dados = [
                                                                                                                                                                                                                                                                                                                                                                                                        produto.codigo,
                                                                                                                                                                                                                                                                                                                                                                                                                    produto.descricao,
                                                                                                                                                                                                                                                                                                                                                                                                                                produto.quantidade,
                                                                                                                                                                                                                                                                                                                                                                                                                                            formatarMoeda(produto.valor),
                                                                                                                                                                                                                                                                                                                                                                                                                                                        formatarMoeda(produto.quantidade * produto.valor)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                ];

                                                                                                                                                                                                                                                                                                                                                                                                                                                                        dados.forEach(dado => {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const celula = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                celula.textContent = dado;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            linha.appendChild(celula);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const acoes = document.createElement("td");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    acoes.className = "acoes";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const botaoEditar = criarBotao("Editar preço", "editar",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        () => atualizarValor(produto.codigo));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const botaoQuantidade = criarBotao("Estoque", "quantidade",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            () => atualizarQuantidade(produto.codigo));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const botaoExcluir = criarBotao("Excluir", "excluir",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                () => excluirProduto(produto.codigo));

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        acoes.append(botaoEditar, botaoQuantidade, botaoExcluir);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                linha.appendChild(acoes);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        tabela.appendChild(linha);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                document.getElementById("mensagemVazia").style.display =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        produtosFiltrados.length === 0 ? "block" : "none";

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            atualizarResumo();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Criar botões de ação
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function criarBotao(texto, classe, acao) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const botao = document.createElement("button");

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    botao.textContent = texto;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        botao.className = classe;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            botao.addEventListener("click", acao);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                return botao;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Formatar valores em reais
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function formatarMoeda(valor) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return valor.toLocaleString("pt-BR", {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            style: "currency",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    currency: "BRL"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Buscar produto pelo código
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function buscarProduto(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return produtos.find(produto => produto.codigo === codigo);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Atualizar valor do produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function atualizarValor(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const produto = buscarProduto(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Produto não encontrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const novoValor = prompt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Digite o novo valor do produto:",
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            produto.valor.toFixed(2)
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (novoValor === null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        const valor = Number(novoValor);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!Number.isFinite(valor) || valor <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    alert("Digite um valor válido!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    produto.valor = valor;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Valor atualizado com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                // Atualizar quantidade do produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                function atualizarQuantidade(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const produto = buscarProduto(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Produto não encontrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const quantidade = prompt(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        "Quantas unidades deseja adicionar ao estoque?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                if (quantidade === null) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    const numero = Number(quantidade);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        if (!Number.isInteger(numero) || numero <= 0) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                alert("Informe uma quantidade válida!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produto.quantidade += numero;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Estoque atualizado com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Excluir produto
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            function excluirProduto(codigo) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const produto = buscarProduto(codigo);

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    if (!produto) {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            alert("Produto não encontrado!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    return;
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const confirmar = confirm(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    "Deseja excluir o produto " + produto.descricao + "?"
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            if (!confirmar) return;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                produtos = produtos.filter(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        produto => produto.codigo !== codigo
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos();

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        alert("Produto excluído com sucesso!");
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Pesquisar produtos
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("pesquisa")
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            .addEventListener("input", function() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    listarProdutos(this.value);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        });

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        // Atualizar informações do estoque
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        function atualizarResumo() {
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            const totalProdutos = produtos.length;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const totalItens = produtos.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (total, produto) => total + produto.quantidade, 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                const valorEstoque = produtos.reduce(
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        (total, produto) =>
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    total + (produto.quantidade * produto.valor), 0
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        );

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            document.getElementById("totalProdutos").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    totalProdutos;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                        document.getElementById("totalItens").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                totalItens;

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                    document.getElementById("valorEstoque").textContent =
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            formatarMoeda(valorEstoque);
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            }

                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            // Iniciar sistema
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            salvarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            listarProdutos();
                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                                            